// Rebuild webvdb.mjs (the committed bundle) from src/: node scripts/vdb/vendor/webvdb/build.mjs
import { build } from 'esbuild';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const here = dirname(fileURLToPath(import.meta.url));
await build({
  entryPoints: [join(here, 'src/entry.ts')],
  outfile: join(here, 'webvdb.mjs'),
  bundle: true, format: 'esm', platform: 'node', target: 'node20', legalComments: 'none',
  alias: { fflate: join(here, 'src/fflate-stub.ts') },
  banner: { js: '// Generated by build.mjs from src/ (WebVDB, Apache-2.0, see NOTICE). Do not edit.' },
});
console.log('wrote webvdb.mjs');
